def tau(n):
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i * i != n:
                count += 1
    return count

def check_solution(n):
    if n <= 0:
        return False

    # Calculate tau(n^12)
    # Since tau is multiplicative, if n = p1^a1 * ... * pk^ak
    # n^12 = p1^(12a1) * ... * pk^(12ak)
    # tau(n^12) = (12a1 + 1) * ... * (12ak + 1)

    import sympy
    try:
        prime_factors = sympy.factorint(n)
    except Exception:
        return False # Should not happen for positive integers

    tau_n_12 = 1
    for exponent in prime_factors.values():
        tau_n_12 *= (12 * exponent + 1)

    return n == tau_n_12

