def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_tau_n_pow_12(n, factors):
    if n == 1:
        return 1
    # n = p1^a1 * p2^a2 * ...
    # n^12 = p1^(12*a1) * p2^(12*a2) * ...
    # tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...

    tau_val = 1
    for exponent in factors.values():
        tau_val *= (12 * exponent + 1)
    return tau_val

def solve_equation(limit):
    solutions = []
    growth_data = []

    for n in range(1, limit + 1):
        if n == 1:
            tau_val = 1
        else:
            factors = get_prime_factorization(n)
            tau_val = calculate_tau_n_pow_12(n, factors)

        is_solution = (n == tau_val)

        if is_solution:
            solutions.append(n)

        growth_data.append((n, tau_val))

    return solutions, growth_data

